fn first_even(v: &[i32]) -> Option<i32> {
    let x = v.iter().find(|n| **n % 2 == 0)?;
    Some(*x)
}
fn main() {
    println!("{:?} {:?}", first_even(&[1, 3, 4]), first_even(&[1, 3]));
}

